QB.push(
/* C7 */
["C7","Which of the following is system software?",["Operating system","MS Word","Tally","VLC media player"],"The operating system controls the computer and is system software; Word, Tally and VLC do user tasks and are application software.","p"],
["C7","A compiler translates a high-level program —",["all at once, into machine code, before it runs","one line at a time while it runs","only from assembly language to machine code","from RAM to the hard disk"],"A compiler converts the whole program in one go and lists the errors afterwards; line-by-line translation is the interpreter's way.","p"],
["C7","Which translator converts and executes a high-level program one statement at a time?",["Interpreter","Compiler","Assembler","Linker"],"An interpreter translates and runs line by line and stops at the first error; a compiler translates the whole program first.","p"],
["C7","An assembler converts —",["assembly language into machine language","high-level language into assembly language","machine language into high-level language","source code into a web page"],"The assembler works only on assembly language (mnemonics such as ADD, MOV); compilers and interpreters handle high-level languages.","p"],
["C7","Which program places an executable program into main memory so that it can run?",["Loader","Linker","Assembler","Debugger"],"The loader (part of the OS) loads the program into RAM; the linker only joins object files into one executable.","p"],
["C7","Which program joins several object files and library files into a single executable file?",["Linker","Loader","Interpreter","Editor"],"The linker combines object modules into one executable; the loader later places that file in memory.",""],
["C7","Machine language, written only in 0s and 1s, belongs to which generation of programming languages?",["First generation","Second generation","Third generation","Fourth generation"],"1GL = machine language, 2GL = assembly language, 3GL = high-level languages such as C and Java.","p"],
["C7","Which of the following is NOT a high-level language?",["Assembly language","COBOL","Python","FORTRAN"],"Assembly language is a low-level (second-generation) language using mnemonics; COBOL, Python and FORTRAN are high-level.",""],
["C7","SQL is generally classed as a language of which generation?",["Fourth generation (4GL)","Second generation (2GL)","First generation (1GL)","Fifth generation (5GL)"],"SQL is a 4GL — you state what data you want, not how to get it; Prolog is the usual 5GL example.",""],
["C7","Which of the following operating systems is open source?",["Linux","Microsoft Windows","macOS","MS-DOS"],"Linux (first released by Linus Torvalds in 1991) is open source; Windows, macOS and MS-DOS are proprietary.","p"],
["C7","The Android operating system is built on which kernel?",["Linux kernel","Windows NT kernel","MS-DOS kernel","Symbian kernel"],"Android, developed by Google, uses a modified Linux kernel; iOS is Apple's mobile OS.",""],
["C7","Which type of operating system is used where a response must come within a fixed time limit, such as air-traffic control or missile guidance?",["Real-time operating system","Batch operating system","Time-sharing operating system","Single-user desktop operating system"],"A real-time OS (RTOS) must respond within strict deadlines; batch systems run collected jobs with no user interaction.","p"],
["C7","In which type of operating system are similar jobs collected and executed together without user interaction?",["Batch processing","Real-time","Time-sharing","Distributed"],"Batch OS groups jobs (like payroll) and runs them in batches; time-sharing gives each user a slice of CPU time.",""],
["C7","An OS that gives each of many users a small slice of CPU time in turn, so all seem to work at once, is called —",["Time-sharing operating system","Batch operating system","Real-time operating system","Embedded operating system"],"Time-sharing divides CPU time into slices among users; real-time is about deadlines, batch about grouped jobs.",""],
["C7","What is the full form of GUI?",["Graphical User Interface","General Utility Interface","Graphical Unified Instruction","Global User Interface"],"GUI uses icons, windows and a mouse (Windows); its opposite is CLI, Command Line Interface (MS-DOS).","p"],
["C7","Which of the following is an example of a Command Line Interface (CLI) operating system?",["MS-DOS","Windows 10","macOS","Android"],"In MS-DOS you type commands at a prompt; Windows, macOS and Android are GUI-based.",""],
["C7","In Windows, where does a file go when it is deleted from the hard disk using the Delete key?",["Recycle Bin","Clipboard","Control Panel","Task Manager"],"Delete moves the file to the Recycle Bin, from where it can be restored; Shift+Delete removes it permanently.","p"],
["C7","Which key combination deletes a selected file in Windows permanently, without sending it to the Recycle Bin?",["Shift+Delete","Ctrl+Delete","Alt+Delete","Ctrl+Shift+Esc"],"Shift+Delete bypasses the Recycle Bin; Ctrl+Shift+Esc opens Task Manager.",""],
["C7","Which pair of file extension and file type is correctly matched?",[".xlsx — Excel workbook",".pptx — Word document",".mp3 — video file",".zip — image file"],".xlsx is an Excel workbook; .pptx is PowerPoint, .mp3 is audio and .zip is a compressed archive.",""],
["C7","A file with the extension .exe is a(n) —",["executable program file","Excel spreadsheet","exported image","plain-text file"],".exe files run directly in Windows; .xlsx is Excel and .txt is plain text.",""],
["C7","Software that can be used free for a trial period, after which the user is asked to pay, is called —",["Shareware","Freeware","Open-source software","Public-domain software"],"Shareware is try-before-you-buy; freeware is free but closed source; open source makes the code public.","p"],
["C7","What is the role of a device driver?",["It lets the operating system communicate with a hardware device","It translates high-level code into machine code","It removes viruses from the computer","It compresses files to save space"],"A device driver (e.g. printer driver) is system software that connects the OS with a specific device.",""],
["C7","BIOS, stored permanently on a chip on the motherboard, is an example of —",["Firmware","Application software","Shareware","Malware"],"Software stored permanently in ROM/flash inside hardware is firmware; BIOS starts the computer during booting.",""],
["C7","Antivirus, Disk Cleanup and disk defragmenter are examples of —",["Utility software","Application software","Programming languages","Firmware"],"Utilities are system software that maintain the computer; they are not application software.",""],

/* C8 */
["C8","Which shortcut undoes the last action?",["Ctrl+Z","Ctrl+Y","Ctrl+U","Ctrl+X"],"Ctrl+Z = Undo, Ctrl+Y = Redo, Ctrl+X = Cut, Ctrl+U = Underline.","p"],
["C8","Ctrl+Y is used to —",["Redo the last undone action","Undo the last action","Open the Run box","Select all"],"Ctrl+Y redoes (or repeats) an action; Ctrl+Z undoes it.",""],
["C8","Which shortcut switches between open programs in Windows?",["Alt+Tab","Ctrl+Tab","Alt+F4","Win+D"],"Alt+Tab switches windows; Ctrl+Tab switches tabs inside a program such as a browser; Alt+F4 closes the window.","p"],
["C8","Alt+F4 in Windows is used to —",["Close the active window or program","Switch to the next window","Open the Task Manager","Show the desktop"],"Alt+F4 closes the active window; on the bare desktop it opens the Shut Down dialog.","p"],
["C8","Which shortcut shows the Windows desktop by minimising all open windows (press again to restore)?",["Win+D","Win+E","Win+L","Win+R"],"Win+D = Desktop, Win+E = File Explorer, Win+L = Lock, Win+R = Run.",""],
["C8","Which shortcut locks a Windows computer?",["Win+L","Win+D","Ctrl+L","Alt+L"],"Win+L locks the PC; Ctrl+L in a browser jumps to the address bar and in Word left-aligns text.","p"],
["C8","Win+E opens —",["File Explorer","Microsoft Edge","Excel","Settings"],"Win+E opens File Explorer; Settings is Win+I.",""],
["C8","Which shortcut opens the Run dialog box in Windows?",["Win+R","Ctrl+R","Alt+R","Win+U"],"Win+R opens Run; Ctrl+R in a browser reloads the page and in Word right-aligns text.",""],
["C8","Which shortcut opens Task Manager directly in Windows?",["Ctrl+Shift+Esc","Ctrl+Alt+Tab","Alt+Shift+Esc","Win+T"],"Ctrl+Shift+Esc opens Task Manager straight away; Ctrl+Alt+Delete first shows the security screen.","p"],
["C8","Which function key is used to rename a selected file or folder in File Explorer?",["F2","F3","F4","F5"],"F2 renames in Windows (in Excel F2 edits the active cell); F5 refreshes.","p"],
["C8","In a web browser such as Chrome, what does Ctrl+D do?",["Bookmarks the current page","Opens the downloads page","Duplicates the tab","Deletes the browsing history"],"In a browser Ctrl+D bookmarks the page; Ctrl+J opens downloads. Note: in Word Ctrl+D opens the Font dialog and in Excel it fills down.","p"],
["C8","In a web browser, which shortcut reloads the page while ignoring the cached copy (hard reload)?",["Ctrl+F5","F5","Ctrl+R","Alt+F5"],"F5 and Ctrl+R do a normal reload; Ctrl+F5 (or Ctrl+Shift+R) forces a fresh download, bypassing the cache.","p"],
["C8","Which browser shortcut reopens the most recently closed tab?",["Ctrl+Shift+T","Ctrl+T","Ctrl+Shift+N","Ctrl+Shift+W"],"Ctrl+Shift+T restores the last closed tab; Ctrl+T opens a new blank tab.",""],
["C8","In Google Chrome, Ctrl+H opens —",["History","Home page","Help","Replace dialog"],"Ctrl+H is History in browsers, but Replace in Word and Excel — read which program the question names.",""],
["C8","In Chrome and Edge, which shortcut opens the Downloads page?",["Ctrl+J","Ctrl+D","Ctrl+H","Ctrl+K"],"Ctrl+J = Downloads, Ctrl+D = bookmark, Ctrl+H = history.",""],
["C8","In Google Chrome, Ctrl+Shift+N opens —",["A new incognito window","A new tab","A new normal window","The bookmarks manager"],"Ctrl+Shift+N opens incognito in Chrome (InPrivate in Edge); Firefox uses Ctrl+Shift+P for a private window.","p"],
["C8","Which of these does NOT move the cursor to the browser's address bar?",["Ctrl+H","Ctrl+L","Alt+D","F6"],"Ctrl+L, Alt+D and F6 all select the address bar; Ctrl+H opens history.",""],
["C8","In MS Office programs, F12 opens the —",["Save As dialog box","Print dialog box","Help window","Open dialog box"],"F12 = Save As in Word, Excel and PowerPoint; in a browser F12 opens developer tools.","p"],
["C8","Which shortcut selects all items or all text?",["Ctrl+A","Ctrl+S","Alt+A","Shift+A"],"Ctrl+A selects all; Ctrl+S saves.",""],
["C8","Ctrl+X is the shortcut for —",["Cut","Exit","Copy","Close"],"Ctrl+X cuts (moves) the selection to the clipboard; Ctrl+C copies it.",""],
["C8","Which shortcut opens a new tab in a web browser?",["Ctrl+T","Ctrl+N","Ctrl+Shift+T","Ctrl+Tab"],"Ctrl+T opens a new tab; Ctrl+N opens a new window and Ctrl+Tab moves to the next tab.",""],
["C8","In a web browser Ctrl+W —",["closes the current tab","opens a new window","saves the web page","opens the bookmarks bar"],"Ctrl+W (or Ctrl+F4) closes the current tab; in Word the same keys close the document.",""],
["C8","Which key combination opens the context (right-click) menu for the selected item?",["Shift+F10","Ctrl+F10","Alt+F1","Shift+F1"],"Shift+F10 works like a right-click; F10 alone activates the menu bar or key tips.",""],
["C8","Pressing F5 in a web browser —",["reloads the current page","starts a slide show","opens the Go To box","opens the search bar"],"F5 reloads in a browser; it starts the show in PowerPoint and opens Go To in Word and Excel.",""],

/* C9 */
["C9","What is the default file extension of a document saved in MS Word 2007 or later?",[".docx",".doc",".dotx",".txt"],".docx is the default since Word 2007; .doc was used in Word 97–2003 and .dotx is a template.","p"],
["C9","Which shortcut inserts a hyperlink in MS Word?",["Ctrl+K","Ctrl+H","Ctrl+L","Ctrl+Shift+H"],"Ctrl+K inserts a hyperlink (also in Excel and PowerPoint); Ctrl+H is Replace.","p"],
["C9","Which shortcut closes the current document in MS Word?",["Ctrl+W","Ctrl+Q","Ctrl+E","Ctrl+C"],"Ctrl+W (or Ctrl+F4) closes the document window; Ctrl+E centres text and Ctrl+C copies.","p"],
["C9","In MS Word, Ctrl+E is used to —",["Center-align the paragraph","Erase the selected text","Open the Edit menu","Export to PDF"],"Ctrl+L left, Ctrl+E center, Ctrl+R right, Ctrl+J justify.","p"],
["C9","Which shortcut justifies a paragraph in MS Word (straight left and right edges)?",["Ctrl+J","Ctrl+L","Ctrl+R","Ctrl+E"],"Ctrl+J = Justify; in a browser the same keys open Downloads.",""],
["C9","Which shortcut inserts a page break in MS Word?",["Ctrl+Enter","Shift+Enter","Alt+Enter","Ctrl+Shift+Enter"],"Ctrl+Enter = page break; Shift+Enter = line break; Ctrl+Shift+Enter = column break.","p"],
["C9","In MS Word, Shift+F3 is used to —",["Change the case of selected text","Open the Find box","Check spelling","Insert a function"],"Shift+F3 cycles lowercase / UPPERCASE / Capitalise Each Word in Word; in Excel it opens Insert Function.","p"],
["C9","In MS Word, Ctrl+] (right square bracket) —",["Increases the font size by 1 point","Decreases the font size by 1 point","Inserts a bracket pair","Indents the paragraph"],"Ctrl+] grows text by 1 pt and Ctrl+[ shrinks it by 1 pt.",""],
["C9","Which key starts the Spelling and Grammar check in MS Word?",["F7","F5","F9","F11"],"F7 runs the spelling and grammar check; Shift+F7 opens the Thesaurus.","p"],
["C9","Shift+F7 in MS Word opens the —",["Thesaurus","Spelling check","Word count","Font dialog"],"Thesaurus (synonyms) is Shift+F7; plain F7 is the spelling and grammar check.",""],
["C9","Mail Merge in MS Word is mainly used to —",["Create personalised letters for many recipients from one document and a data list","Join two Word documents into one","Send a document by email to one person","Combine cells of a table"],"Mail Merge combines a main document with a data source (e.g. an Excel list) to produce many personalised letters, envelopes or labels.","p"],
["C9","Under which tab of MS Word is the Mail Merge feature found?",["Mailings","Insert","Review","References"],"Start Mail Merge, Select Recipients and Finish and Merge are on the Mailings tab.",""],
["C9","Track Changes in MS Word is found under the —",["Review tab","View tab","Insert tab","Home tab"],"Review holds Spelling, Comments, Track Changes and Accept/Reject.",""],
["C9","In MS Word, Ctrl+D opens the —",["Font dialog box","Bookmark dialog box","Delete dialog box","Duplicate page option"],"Ctrl+D opens the Font dialog in Word; in Excel it fills down and in a browser it bookmarks the page.",""],
["C9","Which shortcut opens the Replace dialog in MS Word?",["Ctrl+H","Ctrl+R","Ctrl+F","Ctrl+G"],"Ctrl+H = Replace, Ctrl+F = Find (Navigation pane), Ctrl+G = Go To, Ctrl+R = right align.",""],
["C9","Text that appears at the top of every page of a Word document is called the —",["Header","Footer","Footnote","Title bar"],"The header repeats at the top and the footer at the bottom of every page; both are inserted from the Insert tab.",""],
["C9","Portrait and Landscape are options of —",["Page orientation","Page size","Margins","Text direction"],"Orientation (Layout tab) is portrait (tall) or landscape (wide).",""],
["C9","What is the file extension of a Word template?",[".dotx",".docx",".tmp",".wdt"],"Word templates use .dotx (macro-enabled .dotm); documents use .docx.",""],
["C9","What is the default view in MS Word, which shows the page as it will be printed?",["Print Layout","Draft","Web Layout","Outline"],"Print Layout is the default; Draft hides headers and pictures, Web Layout shows the page as a web page.",""],
["C9","The Format Painter tool in MS Word is used to —",["Copy formatting from one piece of text to another","Draw pictures in a document","Change the page colour","Insert clip art"],"Format Painter (paintbrush, Home tab) copies formatting only, not the text.",""],
["C9","The bar at the bottom of the Word window that shows the page number and word count is the —",["Status bar","Title bar","Ribbon","Quick Access Toolbar"],"The status bar sits at the bottom; the title bar is at the top and shows the document name.",""],
["C9","In MS Word, Ctrl+Home moves the cursor to the —",["Beginning of the document","Beginning of the current line","Home tab","End of the document"],"Ctrl+Home goes to the start of the document; Home alone goes to the start of the line; Ctrl+End to the end.",""],
["C9","Which shortcut inserts a line break (new line within the same paragraph) in MS Word?",["Shift+Enter","Ctrl+Enter","Alt+Enter","Tab+Enter"],"Shift+Enter starts a new line in the same paragraph; Ctrl+Enter inserts a page break. In Excel a new line in a cell is Alt+Enter.",""],

/* C10 */
["C10","Which shortcut creates a new blank workbook in MS Excel?",["Ctrl+N","Ctrl+W","Ctrl+B","Ctrl+O"],"Ctrl+N creates a new workbook; Ctrl+W closes it and Ctrl+O opens an existing one.","p"],
["C10","The intersection of a row and a column in a worksheet is called a —",["Cell","Range","Field","Table"],"A cell is where a row meets a column; a range is a group of cells such as A1:B5.","p"],
["C10","In MS Excel, columns are identified by —",["Letters","Numbers","Roman numerals","Symbols"],"Columns use letters (A, B … XFD) and rows use numbers (1 to 1,048,576).",""],
["C10","How many rows does a worksheet have in Excel 2007 and later versions?",["1,048,576","65,536","16,384","10,48,500"],"Modern Excel has 1,048,576 rows and 16,384 columns; Excel 2003 had 65,536 rows.","p"],
["C10","What is the last column of a worksheet in modern MS Excel?",["XFD","ZZZ","IV","XFZ"],"The 16,384th column is XFD; IV was the last column (256th) in Excel 2003.",""],
["C10","Every formula in MS Excel must begin with —",["= (equal sign)","+ (plus sign)","@ (at sign)","# (hash)"],"Formulas start with = ; text starting with # usually signals an error value.","p"],
["C10","Which of the following is an absolute cell reference?",["$A$1","A1","$A1","A$1"],"$A$1 fixes both column and row; A1 is relative; $A1 and A$1 are mixed.","p"],
["C10","While editing a formula in Excel, which key cycles a reference between relative, absolute and mixed?",["F4","F2","F9","F12"],"F4 cycles A1 → $A$1 → A$1 → $A1; F2 edits the cell and F9 recalculates.","p"],
["C10","In the reference A$1, which part stays fixed when the formula is copied?",["The row (1)","The column (A)","Both column and row","Neither"],"The dollar sign sits before 1, so the row is locked; this is a mixed reference.",""],
["C10","What is the result of the Excel formula =10+5*2?",["20","30","25","17"],"Multiplication comes before addition: 5*2 = 10, then 10+10 = 20. With brackets, =(10+5)*2 gives 30.",""],
["C10","Which function counts all non-empty cells in a range, including text?",["COUNTA","COUNT","COUNTBLANK","SUM"],"COUNTA counts every non-empty cell; COUNT counts only cells containing numbers.","p"],
["C10","VLOOKUP in Excel searches for a value —",["vertically, in the first column of a table","horizontally, in the first row of a table","only in the active cell","in all sheets at once"],"V = vertical (looks down the first column); HLOOKUP looks across the first row.","p"],
["C10","The error #DIV/0! appears in Excel when —",["a number is divided by zero or by an empty cell","the column is too narrow","a function name is misspelt","a referenced cell is deleted"],"#DIV/0! = division by zero; #### = narrow column; #NAME? = misspelt name; #REF! = deleted reference.",""],
["C10","A cell in Excel shows #### (hash signs). What does this usually mean?",["The column is too narrow to display the value","The formula has a spelling mistake","A number is divided by zero","The cell is protected"],"#### is not a formula error — widen the column and the number or date appears.","p"],
["C10","Which Excel error appears when a function name is misspelt, as in =SUMM(A1:A5)?",["#NAME?","#VALUE!","#REF!","#N/A"],"Excel cannot recognise SUMM, so it shows #NAME?; #N/A means a lookup value was not found.",""],
["C10","Which Excel error results when a formula refers to a cell that has been deleted?",["#REF!","#NULL!","#NUM!","#DIV/0!"],"#REF! means an invalid reference, usually after deleting the referred rows, columns or cells.",""],
["C10","Which Excel function returns both the current date and the current time?",["NOW()","TODAY()","DATE()","TIME()"],"NOW() gives date and time; TODAY() gives the date only.",""],
["C10","Which shortcut inserts the current date into an Excel cell?",["Ctrl+;","Ctrl+Shift+;","Ctrl+D","Alt+D"],"Ctrl+; enters today's date and Ctrl+Shift+; the current time; Ctrl+D fills down.","p"],
["C10","Alt+= in MS Excel is the shortcut for —",["AutoSum","Insert Function dialog","Show formulas","New worksheet"],"Alt+= inserts =SUM() for the adjacent numbers (AutoSum); Shift+F3 opens Insert Function.","p"],
["C10","Which key lets you edit the contents of the active cell in Excel?",["F2","F4","F7","F11"],"F2 edits the active cell (in Windows F2 renames a file); F11 creates a chart sheet.",""],
["C10","In MS Excel, Ctrl+D is used to —",["Fill down from the cell above","Open the Font dialog","Bookmark the workbook","Delete the selected row"],"Ctrl+D fills the selection downward (Ctrl+R fills right); in Word Ctrl+D opens the Font dialog.",""],
["C10","Which Excel feature keeps the header row visible while you scroll down a long sheet?",["Freeze Panes","Wrap Text","Merge and Center","Split Cells"],"Freeze Panes (View tab) locks rows or columns on screen; Wrap Text only shows long text on several lines.",""],
["C10","Which shortcut inserts a new worksheet in an Excel workbook?",["Shift+F11","F11","Ctrl+F11","Alt+F11"],"Shift+F11 adds a worksheet; F11 alone creates a chart on a new chart sheet.",""],
["C10","Which file extension is used for a macro-enabled Excel workbook?",[".xlsm",".xlsx",".xls",".xltx"],".xlsm can store macros; .xlsx cannot; .xls is the old 97–2003 format and .xltx is a template.",""],

/* C11 */
["C11","Which key starts a PowerPoint slide show from the first slide?",["F5","Shift+F5","F7","Ctrl+F5"],"F5 starts from the beginning; Shift+F5 starts from the current slide.","p"],
["C11","Shift+F5 in MS PowerPoint —",["starts the slide show from the current slide","starts the slide show from the first slide","inserts a new slide","ends the slide show"],"Shift+F5 = from current slide; F5 = from first slide; Esc ends the show.","p"],
["C11","Which shortcut inserts a new slide in MS PowerPoint?",["Ctrl+M","Ctrl+N","Ctrl+S","Ctrl+D"],"Ctrl+M adds a slide; Ctrl+N creates a whole new presentation and Ctrl+D duplicates a slide.","p"],
["C11","What is the default file extension of a PowerPoint 2007 or later presentation?",[".pptx",".ppt",".ppsx",".potx"],".pptx is the default; .ppt is older, .ppsx opens as a show and .potx is a template.","p"],
["C11","The visual effect shown while moving from one slide to the next is called a —",["Transition","Animation","Theme","Layout"],"Transitions act between slides; animations act on objects within a slide.","p"],
["C11","Which PowerPoint view shows all slides as small thumbnails so they can be rearranged easily?",["Slide Sorter","Notes Page","Reading View","Outline View"],"Slide Sorter shows thumbnails for reordering; Notes Page shows the slide with speaker notes.","p"],
["C11","Which PowerPoint feature lets you change the design of all slides at once?",["Slide Master","Slide Sorter","Rehearse Timings","Hide Slide"],"Editing the Slide Master changes fonts, colours and layouts on every slide.",""],
["C11","Which view in PowerPoint is used to see and print the slide together with the speaker's notes?",["Notes Page","Slide Show","Slide Sorter","Reading View"],"Notes Page shows the slide with its notes below it, as it would print.",""],
["C11","Which key ends a running PowerPoint slide show?",["Esc","F5","Enter","Tab"],"Esc ends the show; Enter or Space moves to the next slide.",""],
["C11","During a PowerPoint slide show, pressing B —",["shows a black screen","goes back one slide","bolds the text","opens the pen tool"],"B blacks out the screen and W shows a white screen; press again to return.",""],
["C11","An effect that makes a picture or bullet fly in within a slide is called —",["Animation","Transition","Slide Master","Design theme"],"Animation acts on objects inside a slide; transition acts between slides.",""],
["C11","In MS PowerPoint, Ctrl+D —",["duplicates the selected slide or object","deletes the selected slide","opens the Font dialog","bookmarks the slide"],"In PowerPoint Ctrl+D duplicates; in Word it opens the Font dialog and in Excel it fills down.",""],
["C11","MS Access is a —",["Database management system","Spreadsheet program","Presentation program","Desktop publishing program"],"Access is the DBMS of MS Office; Excel is the spreadsheet and Publisher does desktop publishing.","p"],
["C11","In a database table, a field that uniquely identifies each record is called the —",["Primary key","Foreign key","Composite field","Index card"],"A primary key must be unique and cannot be empty (like a roll number); a foreign key links to another table's primary key.","p"],
["C11","Which MS Access object is used to present data in a formatted way for printing?",["Report","Form","Query","Table"],"Reports format output for printing; forms are for entering data; queries ask questions; tables store data.",""],
["C11","Which Access object retrieves records that meet given conditions?",["Query","Report","Form","Macro"],"A query selects, sorts or calculates data according to criteria.",""],
["C11","In MS Access, which object provides a user-friendly screen to enter data into a table?",["Form","Report","Query","Module"],"Forms are for data entry and viewing; reports are for printed output.",""],
["C11","What is the default file extension of an MS Access 2007 or later database?",[".accdb",".mdb",".dbf",".acs"],".accdb is the modern format; .mdb was used up to Access 2003.",""],
["C11","In a database table, a single row and a single column are called respectively —",["Record and field","Field and record","Tuple and table","Key and value"],"Each row is a record (one person or item); each column is a field (one attribute).","p"],
["C11","MS Outlook is mainly used for —",["Email, calendar and contacts","Creating presentations","Desktop publishing","Building databases"],"Outlook is an email client and personal information manager; it is not a web browser.",""],
["C11","Which Microsoft application is a digital notebook for free-form notes?",["OneNote","Outlook","Publisher","Access"],"OneNote stores notes in notebooks, sections and pages; Publisher is for brochures and newsletters.",""],
["C11","Google Sheets is the counterpart of which MS Office application?",["Excel","Word","PowerPoint","Access"],"Google Docs = Word, Google Sheets = Excel, Google Slides = PowerPoint.",""],
["C11","LibreOffice Impress, an open-source program, is equivalent to —",["MS PowerPoint","MS Excel","MS Word","MS Access"],"LibreOffice Writer = Word, Calc = Excel, Impress = PowerPoint, Base = Access.",""],
["C11","Which of the following is NOT a part of the Microsoft Office suite?",["Adobe Photoshop","MS Access","MS Outlook","MS OneNote"],"Photoshop is an Adobe image editor; Access, Outlook and OneNote are Office apps.",""]
);
